<?php
declare(strict_types=1);require_once __DIR__.'/../src/db.php';require_once __DIR__.'/../src/auth.php';require_once __DIR__.'/../src/ui.php';require_teacher_or_admin();$pdo=db();$sources=$pdo->query("SELECT ks.*,COALESCE((SELECT COUNT(*) FROM knowledge_chunks kc WHERE kc.source_id=ks.id AND kc.active=true),0) actual_chunks FROM knowledge_sources ks ORDER BY ks.created_at DESC")->fetchAll();$indexed=count(array_filter($sources,fn($x)=>($x['status']??'')==='indexed'));$chunks=array_sum(array_map(fn($x)=>(int)$x['actual_chunks'],$sources));$errors=count(array_filter($sources,fn($x)=>($x['status']??'')==='error'));
$pageTitle='Conteúdos';$pageSubtitle='Biblioteca utilizada pelo professor IA e pelo mecanismo de recuperação de conteúdo.';require __DIR__.'/../templates/header.php';?>
<section class="cards"><article class="card metric-card"><div><div class="label">Fontes cadastradas</div><div class="metric"><?=count($sources)?></div><div class="metric-sub">Documentos e conteúdos</div></div><div class="metric-icon"><?=ui_icon('knowledge')?></div></article><article class="card metric-card"><div><div class="label">Fontes indexadas</div><div class="metric"><?=$indexed?></div><div class="metric-sub">Disponíveis para consulta</div></div><div class="metric-icon"><?=ui_icon('progress')?></div></article><article class="card metric-card"><div><div class="label">Chunks ativos</div><div class="metric"><?=$chunks?></div><div class="metric-sub">Trechos recuperáveis pelo RAG</div></div><div class="metric-icon"><?=ui_icon('curriculum')?></div></article><article class="card metric-card"><div><div class="label">Erros de indexação</div><div class="metric"><?=$errors?></div><div class="metric-sub">Fontes que precisam de atenção</div></div><div class="metric-icon"><?=ui_icon('health')?></div></article></section>
<section class="panel"><div class="panel-head"><div><h2>Biblioteca</h2><p>O total de chunks é calculado diretamente na tabela de conteúdo indexado.</p></div><a class="btn btn-secondary btn-sm" href="/knowledge.php">Atualizar</a></div><?php if(!$sources):?><div class="empty-state"><div class="empty-state-icon"><?=ui_icon('knowledge')?></div><h3>Nenhuma fonte cadastrada</h3><p>Adicione fontes para alimentar as respostas e atividades da Emma.</p></div><?php else:?><div class="table-wrap"><table><thead><tr><th>Fonte</th><th>Nível</th><th>Categoria</th><th>Status</th><th>Chunks ativos</th><th>Indexação</th></tr></thead><tbody><?php foreach($sources as $source):?><tr><td><?php if(file_exists(__DIR__.'/knowledge-source.php')):?><a class="table-link" href="/knowledge-source.php?id=<?=e($source['id'])?>"><strong><?=e($source['title'])?></strong><div class="label"><?=e($source['original_filename']??'')?></div></a><?php else:?><strong><?=e($source['title'])?></strong><div class="label"><?=e($source['original_filename']??'')?></div><?php endif;?></td><td><span class="badge <?=e(ui_level_class($source['level']??''))?>"><?=e($source['level']??'Todos')?></span></td><td><?=e($source['category']??'—')?></td><td><span class="badge <?=e(ui_status_class($source['status']??'pending'))?>"><?=e(ui_status_label($source['status']??'pending'))?></span></td><td><strong><?= (int)$source['actual_chunks']?></strong></td><td><?=e(ui_date($source['indexed_at']??null))?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<?php require __DIR__.'/../templates/footer.php';?>
